pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }
    function testFuzz_property(uint256 plays) public {
        plays = bound(plays, 1, 10);
        for (uint i = 0; i < plays; i++) {
            vm.deal(address(this), 10);
            c.play{value: 10}();
            vm.roll(block.number + 1);
        }
        assertTrue(c.pot() == plays * 10);
    }
}
